def compute(vars):
    goodwill = vars["v1"]
    net_assets_acquired = vars["v2"]
    if net_assets_acquired == 0:
        return None
    value = (goodwill / net_assets_acquired) * 100
    return {
        "value": value,
        "trace": {
            "goodwill": goodwill,
            "net_assets_acquired": net_assets_acquired,
            "ratio": goodwill / net_assets_acquired,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "percentage"
            }
        }
    }
